document.querySelectorAll('.journal-tools select').forEach(select=>select.addEventListener('change',()=>{const filtered=[...document.querySelectorAll('.journal-tools select')].some(s=>s.value!=='all');document.querySelector('#calendar-status').textContent=filtered?'Aucun événement validé ne correspond à ces filtres pour le moment.':'Aucun événement validé n’est publié pour le moment.'}));
